import { join, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { MIGRATIONS_SUBDIR, MIGRATIONS_OLD_SUBDIR, specFiles, oldSpecFiles, migrationActive } from '../engine/checks/helpers/active-migrations.mjs';
import { MODEL_FAMILIES } from '../engine/scheduler/model-map.mjs';

const dir = dirname(fileURLToPath(import.meta.url));

// The migration specs live in a subfolder, so the mechanism (this registry,
// apply.mjs, the fleet passes, the README) reads cleanly beside them and the
// records are a self-contained set. The sync surface — the subfolder name
// (exported so the retire pass can build a record's repo-relative path
// migrations/active_migrations/<file>), the spec listing, and
// `migrationActive` — lives in the vendored engine lib
// (engine/checks/helpers/active-migrations.mjs) because pack CHECKS consult it and packs import
// only the engine surface (pack-independence); this registry re-exports it so
// canon-side callers keep one import home.
export { MIGRATIONS_SUBDIR, MIGRATIONS_OLD_SUBDIR, migrationActive };
const specsDir = join(dir, MIGRATIONS_SUBDIR);
const oldSpecsDir = join(dir, MIGRATIONS_OLD_SUBDIR);

// Structural discovery, like packs/ and skills/: every migration record `.mjs` is a
// spec. The APPLY/backfill path loads from BOTH the recent `active_migrations/` AND
// the aged `migrations-old/` archive (per-project-scheduling redesign), so a dormant
// project baselining out of a fresh canon clone still applies a migration that aged
// past its TTL before it converged — recency governs check-tolerance + what ships in
// the mount, never whether a record still applies. `migrations-old` is canon-only, so
// in a vendored consumer mount it is simply absent (empty) and only the recent records
// load. Each object carries its `file` basename and the `subdir` it lives in, so the
// TTL mover can name records and callers can build a record's repo-relative path.
export async function loadMigrations() {
  const out = [];
  for (const [subdir, dirPath, files] of [
    [MIGRATIONS_SUBDIR, specsDir, specFiles()],
    [MIGRATIONS_OLD_SUBDIR, oldSpecsDir, oldSpecFiles()],
  ]) {
    for (const f of files) {
      const spec = (await import(pathToFileURL(join(dirPath, f)).href)).default;
      out.push({ file: f, subdir, ...spec });
    }
  }
  return out;
}

// Read side — "prefer Y, fall back to X": the ordered list of acceptable paths
// for a canonical target (canonical first, then its legacy aliases). A tolerance
// point consults this instead of hardcoding its own LEGACY_* constant, so a
// rename is declared once here and every reader picks it up. Unknown targets
// resolve to just themselves.
export function resolvePath(migrations, canonical) {
  for (const m of migrations) {
    for (const a of m.aliases ?? []) {
      if (a.canonical === canonical) return [a.canonical, ...(a.legacy ?? [])];
    }
  }
  return [canonical];
}

// Write side — "and rename X -> Y": for each alias whose legacy path still
// exists and whose canonical does not, move legacy -> canonical. `exists` and
// `move` are injected so the same logic drives a local checkout (sync fs) or a
// future API applier (async). Idempotent — a no-op once the rename is done.
export async function applyFileAliases(migration, { exists, move }) {
  const moved = [];
  for (const a of migration.aliases ?? []) {
    for (const legacy of a.legacy ?? []) {
      if ((await exists(legacy)) && !(await exists(a.canonical))) {
        await move(legacy, a.canonical);
        moved.push(`${legacy} -> ${a.canonical}`);
      }
    }
  }
  return moved;
}

// Write side — "vendor these pack templates into the repo": for each declared
// materialization {template, dest}, copy the canon template to its destination
// when the dest is missing or has drifted from the template (idempotent; a
// hand-edited copy self-heals on the next pass). `readTemplate` reads from the
// canon (the pack tree / mounted .claudinite), `read`/`write` act on the consumer
// repo — the source and destination roots differ in a consumer, so they are

  // no pack), plus the ones a fingerprint detects. A seeded pack is still
  // opt-out-able where its own policy allows (baselining re-adds only the packs
  // whose absence it treats as drift), so removing a seeded declaration can
  // stick; each seeded pack ships its own one-time seed migration for the fleet.
  // Local packs are declared by hand, never fingerprinted or seeded — exclude
  // them from --init's seeding so a repo that already carries local packs (but
  // no config yet) doesn't auto-declare them.
  const seeded = packs.filter((p) => p.seededByDefault && !p.local).map((p) => p.id);
  const detected = [...seeded, ...packs.filter((p) => p.detect && !p.local && p.detect(ctx)).map((p) => p.id)];
  // A pack can't be imported without its dependencies — pull each declared pack's
  // `requires` closure into the declaration so it's complete and visible.
  const declared = resolveDeclaredPacks(detected, packs);
  // maintenance.delivery is deliberately materialized, not defaulted — the selection
  // must be visible in the file where a project would change it (see engine/checks/README.md).
  // Only what carries a decision: the declaration and the always-explicit
  // delivery. Empty rules/accept boilerplate is noise, not settings (#385);
  // loadConfig defaults absent keys.
  writeFileSync(path, `${JSON.stringify({ packs: declared, maintenance: { delivery: 'auto-merge' } }, null, 2)}\n`);
  console.log(`Wrote ${path} (packs: ${declared.join(', ')}).`);
  // The adoption interview (surfacing each declared pack's pending questions) is
  // driven by the adopt-claudinite skill / bootstrap.md, and nudged every session
  // by the SessionStart interview-check step — not printed here, so this runner
  // imports no pack.
  process.exit(0);
}

const { packs, errors: packErrors } = await discoverPacks({ localRoot: root });
const ctx = buildContext({ root, mode: has('--changed') ? 'changed' : 'all', baseOverride: value('--base') });

// Settings/load integrity — pack-agnostic, so the world runner owns them.
// Settings validity is checked at load: malformed JSON, an unknown
// property, and a wrong pack name are all equally settings errors. loadConfig
// reports the first two; the runner adds unknown pack names (only it holds the
// registry) and broken/duplicate local pack.mjs faults.
const findings = [];
for (const e of ctx.config.errors) findings.push(configError(e.what, e.fix));
for (const e of packErrors) findings.push(configError(e.what, e.fix));
// knownIds spans canon AND local packs, so a declared local pack id is valid and
// the unknown-pack message lists it among the declarable packs. ctx.config.packs
// is loadConfig's normalized view — bare ids, a namespaced local_packs/<name>
// declaration already resolved through packEntryId.
const knownIds = new Set(packs.map((p) => p.id));
for (const name of ctx.config.packs) {
  if (typeof name === 'string' && !knownIds.has(name)) {
    findings.push(configError(`declares unknown pack "${name}"`, `remove it or fix the name — declarable packs: ${[...knownIds].sort().join(', ')}`));
  }
}
// (Adoption-interview hygiene is a skill-owned check that runs below with the
// other active-pack rules; a malformed `questions` field arrives as a load fault
// in packErrors above. Neither names a pack here.)

// The world rules: everything not scoped to the work. A broken contributedRules
// seam is a config-level fault surfaced here (the world runner owns diagnostics).
findings.push(...runActivePackRules(ctx, packs, {
  includeRule: (rule) => rule.scope !== 'work',
  onContributeError: (pack, e) => findings.push(configError(

1	// baselining worker — the DETERMINISTIC self-refresh, as prework
2	// (task-prework DESIGN §7, E4). This is `agent_model: 'sonnet'` with
3	// `prework: 'node worker.mjs'`, so the scheduler runs THIS FILE as a
4	// subprocess (cwd = this task dir) bounded by `prework_timeout`,
5	// BEFORE any agent. It absorbs everything about the nightly refresh that is
6	// dependency-free code — so most nights are AGENTLESS and quiet, and an agent is
7	// requested only when real judgment is left (owner decision, 2026-07-23):
8	//
9	//   agent requested  ⇔  a pending AGENTIC migration note exists
10	//                    OR  the converge changed things AND check_the_world is not green.
11	//   no change, or changed-but-green with no agentic note  →  agentless night.
12	//
13	// What it does, Action-side, over the one sanctioned non-MCP surface (the Action
14	// GITHUB_TOKEN in env) and a direct PUBLIC canon fetch (owner §10: canon is
15	// public — no token, no tarball channel):
16	//   1. shallow-clone canon at its head sha (then drop .git → a rootless tree, so
17	//      apply-vendor-set skips the ancestry guards that a shallow clone can't
18	//      satisfy — it is head by construction);
19	//   2. run the CLONED canon's vendoring/apply-vendor-set.mjs to converge
20	//      .claudinite/shared/ and stamp it (compute+apply, one snapshot);
21	//   3. run the cloned converge-wiring.mjs (scheduler workflow + hashed cron + the
22	//      tasks' declared required_secrets, settings hooks, retired-import removal),
23	//      and ask the owner for any declared secret the repo hasn't configured;
24	//   4. apply the MECHANICAL migration notes (aliases/materialize/rewrite/declarePacks)
25	//      via the cloned migrations/apply.mjs — idempotent — and re-converge the mount
26	//      when that changed the DECLARATION, since a newly declared pack's content was
27	//      not in the set the vendor pass computed a moment earlier;
28	//   5. detect pending AGENTIC notes (registry.mjs `agenticMigrations`, gated on
29	//      the prior stamp day, same-day inclusive #330) and, if any, HOLD the stamp
30	//      at the day before the earliest one so the agent still sees the note (the
31	//      stamp/agentic coupling rule);
32	//   6. deliver the converge as ONE commit on the per-cycle maintenance branch via
33	//      NATIVE git (dispose of the family's open PR — merge it if its own runs
34	//      verified it, else close it — then cut a fresh dated branch and open the
35	//      PR), arming auto-merge per the
36	//      member's `maintenance.delivery` and DISPATCHING the repo's PR CI on the
37	//      branch — the GITHUB_TOKEN push emits no pull_request run of its own
38	//      (#565), so the checks the arm waits on must be started explicitly;
39	//   7. request the agent (write CLAUDINITE_REQUEST_AGENT) only when judgment is
40	//      left — the scheduler files `ready-for-agent` iff this file appears (§3,
41	//      conditional handoff). NO code→agent data channel: the file is a pure
42	//      control signal; the agent discovers its work by reading the repo (the
43	//      pushed branch, the held stamp, the pending note).
44	//
45	// Imports: node builtins, plus the vendored ENGINE SURFACE — the one import the
46	// pack-independence barrier sanctions. The delivery/landing nuances live in
47	// `engine/scheduler/land-pr.mjs` (one home for every PR-delivering task; its
48	// helpers grew here and moved out), vendored beside this worker and loaded at
49	// process start — so the mid-run mount overwrite (apply-vendor-set rewriting the
50	// tree this process is executing from) can never mix an old worker with new
51	// landing logic. The vendoring/migrations machinery stays canon-internal
52	// (vendoring/ is never vendored, #385), so the worker INVOKES the
53	// freshly-fetched canon's scripts as subprocesses and DYNAMIC-imports its
54	// registry from the temp clone path — never a static import of that code.
55	//
56	// This SUPERSEDES the per-cycle maintenance-branch naming of PR #407 (that PR
57	// reworked the OLD fleet-apply MCP path; baselining's delivery is native git
58	// Action-side and carries its own prefix/find-by-prefix here).
