60	import { execFileSync } from 'node:child_process';
61	import { readFileSync, writeFileSync, existsSync, rmSync, mkdtempSync } from 'node:fs';
62	import { join } from 'node:path';
63	import { tmpdir } from 'node:os';
64	import { pathToFileURL } from 'node:url';
65	// The shared landing helpers (see the header note): delivery resolution, the
66	// PR-open status check, and the whole arm/land/merge decision live there — this
67	// worker keeps only what is baselining-shaped (the family branch and its
68	// close-and-recut disposal).
69	import {
70	  resolveDelivery, pullCreateError, landDelivery,
71	  pullDisposition, mergeReason, failureSummary, deleteBranch,
72	} from '../../../../engine/scheduler/land-pr.mjs';
73	
74	const CANON_URL = 'https://github.com/missingbulb/Claudinite.git'; // public — no token
75	const MAINT_PREFIX = 'claudinite/maintenance';
76	const API = 'https://api.github.com';
77	
78	// --- pure helpers (exported, unit-tested git-free) --------------------------
79	
80	// The pending AGENTIC notes: those dated on/after the DAY of the prior stamp
81	// (same-day inclusive, #330), oldest first. `agenticList` is registry.mjs
82	// `agenticMigrations(all)` — already filtered to records carrying a valid
83	// `agentic` note (a malformed note throws THERE, aborting the run loudly).
84	export function pendingAgentic(agenticList, priorUpdated) {
85	  const priorDay = String(priorUpdated ?? '').slice(0, 10);
86	  return [...(agenticList ?? [])]
87	    .filter((m) => !priorDay || String(m.landed) >= priorDay)
88	    .sort((a, b) => String(a.landed).localeCompare(String(b.landed)));
89	}
90	
91	// HOLD the stamp at the day before the earliest pending agentic note (the
92	// stamp/agentic coupling rule): the note stays selected next run until the agent
93	// lands it and advances the stamp itself. Returns the held ISO datetime, or null
94	// when nothing is pending (the stamp advances normally).
95	export function heldStamp(pending) {
96	  if (!pending?.length) return null;
97	  const d = new Date(`${String(pending[0].landed).slice(0, 10)}T00:00:00.000Z`);
98	  d.setUTCDate(d.getUTCDate() - 1);
99	  return d.toISOString();
100	}
101	
102	// A per-cycle maintenance branch name — dated + a short seed so each cycle gets a
103	// distinct branch (superseding #407's scheme, native-git side). `seed` is passed
104	// in so this is pure; main() generates it.
105	export function maintenanceBranchName(dateStr, seed) {
106	  return `${MAINT_PREFIX}-${dateStr}-${seed}`;
107	}
108	
109	// The family's open maintenance PR, found by head-branch PREFIX (the name carries
110	// a per-cycle seed, so the prefix is what identifies the family): the cycle
111	// DISPOSES of this one — merge or close — before cutting its own, which is what
112	// keeps them from piling up night-over-night. null → nothing to dispose of. The
113	// whole PR is returned, not just its ref, because disposal needs its number and
114	// head sha.
115	export function openMaintenancePull(pulls, prefix = MAINT_PREFIX) {
116	  return (pulls ?? []).find((pr) => String(pr?.head?.ref ?? '').startsWith(prefix)) ?? null;
117	}
118	
119	// Its head branch alone — the shape most callers want.
120	export function openMaintenanceBranch(pulls, prefix = MAINT_PREFIX) {
121	  return openMaintenancePull(pulls, prefix)?.head?.ref ?? null;
122	}
123	
124	// The paths this stage is STRUCTURALLY UNABLE to deliver. deliver() pushes with the
125	// Action's GITHUB_TOKEN, and GitHub refuses to let that token create or update anything
126	// under `.github/workflows/` — there is no `permissions:` key that grants it. The refusal
127	// is remote-side and rejects the WHOLE ref, so a workflow file left in the commit fails
128	// the entire push, taking the mount convergence, the wiring and every other note with it.
129	//
130	// So the converge withholds exactly these paths and hands them to the AGENT stage, whose
131	// writes go through the session's MCP GitHub tools — a credential that does hold the
132	// `workflows` permission. The agent re-runs the same mechanical apply in its own checkout
133	// to produce them.
134	//
135	// It covers `convergeWiring`'s scheduler workflow as much as any pack-owned one.
136	export const UNPUSHABLE_PREFIX = '.github/workflows/';
137	export function withheldWorkflowPaths(changedPaths) {
138	  return (changedPaths ?? []).filter((p) => p.startsWith(UNPUSHABLE_PREFIX));
139	}
140	
141	// The escalation decision (owner, 2026-07-23): agent iff a pending agentic note,
142	// or a real change the deterministic converge left non-green. No change, or a
143	// green change with no agentic note, stays agentless.
144	//
145	// It returns the REASON, not a bit — `null` for an agentless night, otherwise
146	// `{ code, detail }`. The worker knew which of four conditions fired and then threw
147	// it away; the agent it woke re-derived all four from scratch, and on
148	// EdFringeAllocator#82 re-derived them WRONG (it reported "preprocessing created
149	// nothing" about a cycle that had merged its PR a second earlier) and closed a
150	// six-minute run as a no-op. `code` is the stable identifier a consumer branches on;
151	// `detail` is the sentence a human reads in the dispatch issue.
152	//
153	// It names the CONDITION and its counts, never the findings themselves — those stay
154	// in the repo for the agent to re-run (DESIGN §3, the no-code→agent-data-channel rule;
155	// the named exception is identity, not content).
156	//
157	// The branch ORDER is the escalation precedence, most-specific first: a night with a
158	// pending note and a red check is a note night, because the note is what the agent
159	// must apply and the red check may well be the note's own doing.
160	export function escalation({
161	  pendingCount, meaningfulChange, checksPass, selftestOk = true, withheldCount = 0,
162	  checksCrashed = false, selftestCrashed = false,
163	}) {
164	  if (pendingCount > 0) {
165	    return { code: 'agentic-notes', detail: `${pendingCount} pending agentic migration note(s) to apply` };
166	  }
167	  // A withheld workflow file is work this stage COULD not do, not work it chose to
168	  // leave: without the agent, the file simply never lands, and the converge would
169	  // report itself clean while the repo stays un-updated.
170	  if (withheldCount > 0) {
171	    return {
172	      code: 'withheld-workflows',
173	      detail: `${withheldCount} workflow file(s) the Action token cannot push — only the agent's credential can land them`,
174	    };
175	  }
176	  // A converged mount that cannot pass its own self-test is the judgment case
177	  // whether or not the converge "changed" anything a diff can see: broken
178	  // machinery reports no findings precisely because it is not running.
179	  if (!selftestOk) {
180	    return selftestCrashed
181	      ? { code: 'selftest-could-not-run', detail: 'the converged mount\'s self-test could not run at all — machinery, not content' }
182	      : { code: 'selftest-failed', detail: 'the converged mount FAILED its self-test — the machinery that runs the rules is not intact' };
183	  }
184	  if (Boolean(meaningfulChange) && !checksPass) {
185	    return checksCrashed
186	      ? { code: 'checks-could-not-run', detail: 'check_the_world could not run on the converged tree — no verdict was produced' }
187	      : { code: 'checks-not-green', detail: 'check_the_world reported findings on the converged tree that the deterministic pass could not fix' };
188	  }
189	  return null;
190	}
191	
192	// The same decision as a bit, for the callers that only need the verdict. Derived
193	// rather than reimplemented — two copies of a four-branch precedence is exactly the
194	// drift the corpus forbids.
195	export function shouldRequestAgent(signals) {
196	  return escalation(signals) !== null;
197	}
198	
199	// The scheduler hands the worker a path to signal the agent through; writing it
200	// requests the agent stage (run.mjs files `ready-for-agent` iff it appears).
201	export const AGENT_REQUEST_MARKER = 'agent-requested';
202	
203	// --- I/O shell (validated by the live pilot, not unit tests) ----------------
204	
205	const git = (args, opts = {}) =>
206	  execFileSync('git', args, { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], ...opts });
207	// `opts` exists for ONE reason: `cwd`. This worker's own cwd is the task dir INSIDE the
208	// mount (prework.mjs spawns it there), and step 2 deletes that whole tree before
209	// re-copying it — so from the vendor step onward this process is running in an unlinked
210	// directory, and every child it spawns inherits it. A child that calls `process.cwd()`
211	// dies with `ENOENT … uv_cwd` (#689). Children are therefore pointed at the repo root,
212	// which is the directory they were always meant to be working in.
213	const node = (args, extraEnv = {}, opts = {}) =>
214	  execFileSync(process.execPath, args, {
215	    encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'], env: { ...process.env, ...extraEnv }, ...opts,
216	  });
217	
218	async function gh(token, path, { method = 'GET', body } = {}) {
219	  const res = await fetch(`${API}${path}`, {
220	    method,
221	    headers: {
222	      authorization: `Bearer ${token}`,
223	      accept: 'application/vnd.github+json',
224	      'x-github-api-version': '2022-11-28',
225	      ...(body ? { 'content-type': 'application/json' } : {}),
226	    },
227	    body: body ? JSON.stringify(body) : undefined,
228	  });
229	  let json = null;
230	  try { json = await res.json(); } catch { /* empty body */ }
231	  return { status: res.status, json };
232	}
233	
234	// The outcome of running one gate script, from what `node()` threw (or didn't).
235	// PURE, so the four shapes are testable without a repo on disk.
236	//
237	// `catch { return false }` was the whole of this before, and it collapsed four
238	// different events into one indistinguishable bit: findings, a crash, a signal kill,
239	// and a script that isn't there. `node()` already pipes stdout/stderr, so the
240	// findings were in the thrown error's `.stdout` all along and the bare catch dropped
241	// them — leaving the escalation they caused unexplainable after the fact
242	// (EdFringeAllocator#82: a run that escalated on a check which passes everywhere it
243	// can be re-run, with no record of what it saw).
244	//
245	// `crashed` is the distinction that matters most: a non-zero EXIT is a verdict about
246	// the repo's content, while a null status — signal kill, spawn failure — means no
247	// verdict was produced at all. Both still escalate to the agent (a gate that cannot
248	// answer is not permission to proceed), but they are no longer the same sentence.
249	export function gateOutcome(error) {
250	  if (!error) return { ok: true, ran: true, crashed: false, status: 0, output: '' };
251	  const status = Number.isInteger(error.status) ? error.status : null;
252	  const output = `${error.stdout ?? ''}${error.stderr ?? ''}`.trim();
253	  return { ok: false, ran: true, crashed: status === null, status, output };
254	}
255	
256	// A gate that isn't vendored at all is nothing to run — not a failure. Distinct from
257	// `crashed`, which is a gate that exists and could not answer.
258	export const GATE_ABSENT = Object.freeze({ ok: true, ran: false, crashed: false, status: null, output: '' });
259	
260	// Run check_the_world against the converged repo. Green means it exited clean (no
261	// blocking findings); anything else is judgment left, with the reason attached.
262	function runCheckTheWorld(root) {
263	  const cw = join(root, '.claudinite/shared/engine/checks/check_the_world.mjs');
264	  if (!existsSync(cw)) return GATE_ABSENT; // no vendored checks to gate on
265	  try { node([cw], { CLAUDE_PROJECT_DIR: root }, { cwd: root }); return gateOutcome(null); }
266	  catch (e) { return gateOutcome(e); }
267	}
268	
269	// REHEARSAL MODE (per-project-scheduling rehearsal, #593 phase 0). A run may be
270	// pointed at a canon BRANCH instead of its default head, so a canon change can be
271	// tried against a real repo before it merges. `CLAUDINITE_CANON_REF` selects the
272	// ref; `CLAUDINITE_CANON_URL` a fork.
273	//
274	// The stamp is the whole reason this needs its own decision rather than an extra
275	// clone argument. A branch head is NOT on trunk, and stamping it is precisely the
276	// shape vendoring's #328 anti-rewind guard refuses to write over afterwards
277	// (`ref-not-on-trunk`, which the sheepdog freshness sweep reads as WEDGED, not
278	// late) — a rehearsal would leave the repo unable to baseline ever again. This
279	// was not hypothetical: it happened by hand on 2026-07-30, to all thirteen
280	// members at once, from a converge run out of an unmerged branch.
281	//
282	// So a rehearsal stamps NOTHING. It converges, it reports, and it leaves the
283	// member's provenance exactly as it found it.
284	export function canonSource(env = {}) {
285	  const ref = String(env.CLAUDINITE_CANON_REF ?? '').trim();
286	  const url = String(env.CLAUDINITE_CANON_URL ?? '').trim() || CANON_URL;
287	  return { url, ref: ref || null, rehearsal: Boolean(ref) };
288	}
289	
290	// Run the engine's self-test against the converged tree; green when the machinery
291	// is intact. Same soft shape as runCheckTheWorld — a missing selftest (an older
292	// mount that predates it) is not a failure, it is nothing to run.
293	function runSelfTest(root) {
294	  const st = join(root, '.claudinite/shared/engine/selftest.mjs');
295	  if (!existsSync(st)) return GATE_ABSENT;
296	  try { node([st, '--strict'], { CLAUDE_PROJECT_DIR: root }, { cwd: root }); return gateOutcome(null); }
297	  catch (e) { return gateOutcome(e); }
298	}
299	
300	// What a gate said, for the LOG — the full text, not a summary. This is the one
301	// place the findings belong: the Action log is an observability surface nothing
302	// reads programmatically, so it carries everything, while the dispatch issue
303	// carries only the condition (preprocess.mjs, the §3 exception).
304	function logGateOutput(label, outcome) {
305	  const body = outcome.output ? `\n${outcome.output}` : ' (no output)';
306	  console.log(`baselining: ${label} ${outcome.crashed ? 'COULD NOT RUN' : `exited ${outcome.status}`} —${body}`);
307	}
308	
309	// Deliver the converge as one commit on a FRESH per-cycle maintenance branch,
310	// native git: dispose of the family's open PR first (merge it if last cycle's
311	// content is verified, otherwise close it), then cut a new dated branch + PR and
312	// arm auto-merge when the member asked for it.
313	//
314	// Nothing is reused. A maintenance PR is one cycle's deterministic converge, and
315	// a cycle that did not land has nothing to hand the next one — inheriting it is
316	// what turned a single failed arm into a PR that outlived every subsequent cycle
317	// (#455/#205/#95). The disposal happens BEFORE the converge is pushed, because
318	// the push would replace the head sha the merge evidence hangs on.
319	async function deliver(root, repo, base, token, delivery, seed, withheld = []) {
320	  const { json: pulls } = await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);
321	  const openPr = openMaintenancePull(Array.isArray(pulls) ? pulls : []);
322	  let pr = null;
323	  let merged = false;
324	
325	  if (openPr?.number) {
326	    // `wait` is the one case that keeps the PR: its checks are still running and
327	    // may yet land it. Skip this cycle entirely rather than race them — the
328	    // converge is idempotent, so tomorrow simply does it again.
329	    const kept = await disposeOpenPull(token, repo, openPr, delivery)
330	      .catch((e) => { console.log(`baselining: disposing of PR #${openPr.number} failed: ${e.message}`); return openPr; });
331	    if (kept) {
332	      console.log(`baselining: PR #${openPr.number} still stands — leaving this cycle's converge undelivered`);
333	      // Same shape as the delivery path below — the caller reads `.branch`/`.pr`
334	      // unconditionally, and the bare-ref return this used to make crashed it.
335	      return { branch: kept.head?.ref ?? null, pr: kept.number ?? openPr.number, merged: false };
336	    }
337	  }
338	
339	  const branch = maintenanceBranchName(new Date().toISOString().slice(0, 10), seed);
340	
341	  git(['-C', root, 'checkout', '-B', branch]);
342	  git(['-C', root, 'add', '-A']);
343	  // Withhold what this token cannot push (see withheldWorkflowPaths). Unstaged, not
344	  // reverted: the file stays in the working tree so nothing here has to reason about
345	  // restoring it, and the runner is discarded at job end either way. The agent lands
346	  // them on this same branch afterwards.
347	  for (const p of withheld) git(['-C', root, 'restore', '--staged', p]);
348	  // With everything else staged, a converge whose ONLY content was a workflow file has
349	  // nothing left to commit. It still needs the branch and the PR — that is where the
350	  // agent does its half — so the commit is allowed to be empty rather than skipped.
351	  const staged = git(['-C', root, 'diff', '--cached', '--name-only']).split('\n').filter(Boolean);
352	  const note = withheld.length
353	    ? `\n\nWithheld for the agent stage (the Action token cannot push a workflow file):\n${withheld.map((p) => `- ${p}`).join('\n')}`
354	    : '';
355	  git(['-C', root, '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
356	    'commit', ...(staged.length ? [] : ['--allow-empty']),
357	    '-m', `Claudinite maintenance: converge vendored mount, wiring, and migration notes${note}`]);
358	  const remote = `https://x-access-token:${token}@github.com/${repo}.git`;
359	  git(['-C', root, 'push', '--force', remote, `HEAD:refs/heads/${branch}`]);
360	
361	  const body = delivery === 'auto-merge'
362	    ? 'Automated Claudinite maintenance (deterministic converge + any migration notes). Re-cut each cycle; auto-merges once this repo\'s checks pass.'
363	    : 'Automated Claudinite maintenance (deterministic converge + any migration notes). Re-cut each cycle; left for your review.';
364	  const created = await gh(token, `/repos/${repo}/pulls`, {
365	    method: 'POST', body: { head: branch, base, title: 'Claudinite maintenance', body },
366	  });
367	  const failure = pullCreateError(created.status, created.json);
368	  if (failure) throw new Error(`could not open the maintenance PR for ${branch}: ${failure}`);
369	  pr = created.json;
370	
371	  // Land what was just pushed, per the member's delivery and the repo's own
372	  // shape — the shared helper owns every nuance (land-pr.mjs): it starts the
373	  // PR's checks (#565), reads what the base branch requires, then merges
374	  // directly (no PR CI), verifies-then-lands (ungated base — the arm would be
375	  // rejected "clean status" every cycle, #677), or arms auto-merge with the
376	  // landing poll as fallback (#649). An arm that still could not land costs one
377	  // cycle, not forever: the next cycle merges this PR on its concluded runs
378	  // (pullDisposition) or closes it and re-cuts. Idempotent either way.
379	  if (pr?.number) {
380	    const landed = await landDelivery({
381	      token, repo, base, delivery, pr,
382	      log: (s) => console.log(`baselining: ${s}`),
383	    });
384	    merged = landed.merged;
385	  }
386	  // What this cycle delivered. The scheduler records it in the dispatch issue, which is
387	  // the agent's source for these artifacts.
388	  return { branch, pr: pr?.number ?? null, merged };
389	}
390	
391	// The I/O half of the disposal: read the workflow runs for the open PR's head
392	// sha, decide with pullDisposition, and either merge it (last cycle's content is
393	// verified — the arm just never landed it) or close it and delete its branch so
394	// this cycle re-cuts from scratch. Returns the PR when it still stands (a `wait`,
395	// a `review` member, or a failed attempt), null when the way is clear.
396	//
397	// Best-effort throughout: anything unreadable or unmergeable leaves the PR as it
398	// found it, and the cycle skips rather than piling a second PR on top.
399	async function disposeOpenPull(token, repo, pr, delivery) {
400	  const { status, json } = await gh(token, `/repos/${repo}/actions/runs?head_sha=${pr.head?.sha}&per_page=100`);
401	  if (status !== 200) {
402	    console.log(`baselining: could not read the runs for PR #${pr.number}'s head (HTTP ${status})`);
403	    return pr;
404	  }
405	  const runs = (json?.workflow_runs ?? []).map((r) => ({ name: r.name, status: r.status, conclusion: r.conclusion }));
406	  const disposition = pullDisposition({ delivery, runs });
407	
408	  if (disposition === 'keep' || disposition === 'wait') {
409	    console.log(`baselining: keeping PR #${pr.number} (${disposition})`);
410	    return pr;
411	  }
412	
413	  if (disposition === 'merge') {
414	    const res = await gh(token, `/repos/${repo}/pulls/${pr.number}/merge`, {
415	      method: 'PUT', body: { merge_method: 'squash' },
416	    });
417	    if (res.status === 200) {
418	      console.log(`baselining: merged PR #${pr.number} — ${mergeReason(runs)}`);
419	      await deleteBranch({ token, repo, ref: pr.head?.ref, log: (s) => console.log(`baselining: ${s}`) });
420	      return null;
421	    }
422	    console.log(`baselining: could not merge PR #${pr.number} (${res.status}: ${res.json?.message ?? 'no message'})`
423	      + ' — closing it instead; the converge is idempotent and this cycle re-cuts it');
424	  }
425	
426	  // Closed, not left to rot: whatever went wrong on that head, the next converge
427	  // reproduces the same content from the same inputs. Named in the log because a
428	  // member closing its maintenance PR every single night is a repo whose CI needs
429	  // a human, and the pattern has to be visible to be noticed.
430	  const closed = await gh(token, `/repos/${repo}/pulls/${pr.number}`, { method: 'PATCH', body: { state: 'closed' } });
431	  if (closed.status !== 200) {
432	    console.log(`baselining: could not close PR #${pr.number} (${closed.status}) — leaving it and skipping this cycle`);
433	    return pr;
434	  }
435	  console.log(`baselining: closed PR #${pr.number} — it did not land (${failureSummary(runs)}); re-cutting this cycle`);
436	  await deleteBranch({ token, repo, ref: pr.head?.ref, log: (s) => console.log(`baselining: ${s}`) });
437	  return null;
438	}
439	
440	// Ask the owner to add a repo Actions secret a task declares in `required_secrets`
441	// but the repo has not configured. The wiring converge stamps every declared name
442	// into the scheduler workflow, so by the time this runs the value is either in the
443	// environment or genuinely unset — no separate probe needed.
444	//
445	// This is the adoption interview's posture, not a gate: nothing fails, no check
446	// fires, and the task that needs the secret simply doesn't work until someone adds
447	// it. One open issue per repo (matched by exact title) so an unconfigured secret
448	// costs one issue, not one per night. Exported for the tests.
449	export const SECRETS_ISSUE_TITLE = 'Claudinite: configure required Actions secrets';
450	
451	export function unconfiguredSecrets(declared, env) {
452	  return (declared ?? []).filter((name) => !env[name]);
453	}
454	
455	async function askForSecrets(token, repo, names) {
456	  const q = encodeURIComponent(`repo:${repo} in:title "${SECRETS_ISSUE_TITLE}" state:open`);
457	  const { json } = await gh(token, `/search/issues?q=${q}&per_page=10`);
458	  if ((json?.items ?? []).some((i) => (i.title ?? '').trim() === SECRETS_ISSUE_TITLE)) return false;
459	  const body = [
460	    'A scheduled task in this repo declares a repo **Actions secret** that is not configured yet.',
461	    'Until it is, that task cannot do its work — everything else keeps running normally.',
462	    '',
463	    ...names.map((n) => `- \`${n}\``),
464	    '',
465	    `Add each one at https://github.com/${repo}/settings/secrets/actions, then close this issue.`,
466	  ].join('\n');
467	  await gh(token, `/repos/${repo}/issues`, { method: 'POST', body: { title: SECRETS_ISSUE_TITLE, body } });
468	  return true;
469	}
470	
471	export async function main() {
472	  const root = process.env.CLAUDINITE_REPO_ROOT || process.cwd();
473	  const repo = process.env.CLAUDINITE_REPO || process.env.GITHUB_REPOSITORY;
474	  const base = process.env.CLAUDINITE_DEFAULT_BRANCH || 'main';
475	  const token = process.env.GITHUB_TOKEN;
476	  const requestFile = process.env.CLAUDINITE_REQUEST_AGENT;
477	  // Set by deliver() to `{ branch, pr, merged }`; stays null when this cycle opened
478	  // nothing, which is what the dispatch issue then says.
479	  let delivered = null;
480	  if (!repo) { console.error('baselining: no repo (CLAUDINITE_REPO/GITHUB_REPOSITORY)'); process.exit(1); }
481	  if (!token) { console.error('baselining: no GITHUB_TOKEN in env'); process.exit(1); }
482	
483	  const checksPath = join(root, '.claudinite-checks.json');
484	  if (!existsSync(checksPath)) { console.log('baselining: no .claudinite-checks.json — nothing to self-refresh'); return; }
485	  const priorRaw = JSON.parse(readFileSync(checksPath, 'utf8'));
486	  const priorStamp = priorRaw.claudinite ?? {};
487	  if (!priorStamp.updated && !priorStamp.ref) {
488	    console.log('baselining: no vendored-mount stamp — nothing to self-refresh (canon home or pre-adoption)');
489	    return; // quiet, no agent (matches the precondition self-skip)
490	  }
491	  const { delivery, materialize } = resolveDelivery(priorRaw?.maintenance?.delivery);
492	  if (!delivery) {
493	    console.error(`baselining: maintenance.delivery "${priorRaw?.maintenance?.delivery}" is neither auto-merge nor review`);
494	    process.exit(1);
495	  }
496	  // Materialize the missing key BEFORE the converge, so the repair rides this
497	  // cycle's maintenance commit like any other converged surface.
498	  if (materialize) {
499	    priorRaw.maintenance = { ...priorRaw.maintenance, delivery };
500	    writeFileSync(checksPath, JSON.stringify(priorRaw, null, 2) + '\n');
501	    console.log(`baselining: maintenance.delivery was missing — materialized "${delivery}"`);
502	  }
503	
504	  // 1. Fetch canon at head as a ROOTLESS tree (drop .git so apply-vendor-set's
505	  //    ancestry guards skip — a shallow clone can't answer them, and it is head
506	  //    by construction).
507	  const source = canonSource(process.env);
508	  const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
509	  git(source.ref
510	    ? ['clone', '--depth', '1', '--branch', source.ref, source.url, tmp]
511	    : ['clone', '--depth', '1', source.url, tmp]);
512	  const headSha = git(['-C', tmp, 'rev-parse', 'HEAD']).trim();
513	  rmSync(join(tmp, '.git'), { recursive: true, force: true });
514	  if (source.rehearsal) {
515	    console.log(`baselining: REHEARSAL against ${source.url}@${source.ref} (${headSha.slice(0, 8)}) — `
516	      + 'the stamp will be restored, and nothing is delivered');
517	  }
518	
519	  // 2-4. Deterministic converge: mount + stamp, then wiring, then mechanical notes.
520	  node([join(tmp, 'vendoring/apply-vendor-set.mjs'), '--target', root, '--ref', headSha]);
521	  const wiringOut = node([join(tmp, 'engine/scheduler/converge-wiring.mjs'), repo], { CLAUDINITE_REPO_ROOT: root });
522	  // The handshake (migrations/registry.mjs, WITHHOLD_CAPABLE_ENV): THIS worker withholds
523	  // workflow paths from its commit and hands them to the agent, so a record may safely
524	  // materialize one. An older vendored worker does not set it and the materialization is
525	  // skipped instead of wedging its push. Set here, by the code that does the withholding,
526	  // because the question is what the RUNNING process can do — and the disk cannot answer
527	  // it: apply-vendor-set above has already overwritten this very file with the new
528	  // version while this old-or-new code is the thing actually executing.
529	  const declarationBefore = readFileSync(checksPath, 'utf8');
530	  node([join(tmp, 'migrations/apply.mjs')], { CLAUDE_PROJECT_DIR: root, CLAUDINITE_CAN_WITHHOLD_WORKFLOWS: '1' });
531	  // A note may have DECLARED a pack (the seed shape). The mount above was computed
532	  // from the declaration as it stood a moment ago, so the new pack's content is not
533	  // in it — and a declared pack whose code is absent is a BLOCKING config error until
534	  // something re-converges. Re-run the vendor pass when, and only when, the
535	  // declaration actually changed: it is whole-set convergence over a local tree, so
536	  // the cost is small and the result identical when nothing moved.
537	  if (readFileSync(checksPath, 'utf8') !== declarationBefore) {
538	    console.log('baselining: a migration note changed the declaration — re-converging the mount');
539	    node([join(tmp, 'vendoring/apply-vendor-set.mjs'), '--target', root, '--ref', headSha]);
540	  }
541	
542	  // Ask about any declared secret the repo hasn't configured — but only once the
543	  // wiring is settled. On the cycle that FIRST stamps a name into the workflow the
544	  // value cannot be in this process's env yet, so asking then would nag about a
545	  // secret the owner may well have already added; next cycle tells the truth.
546	  const { declaredSecrets } = await import(pathToFileURL(join(tmp, 'engine/scheduler/converge-wiring.mjs')).href);
547	  const missingSecrets = wiringOut.includes('.github/workflows/claudinite-scheduler.yml')
548	    ? []
549	    : unconfiguredSecrets(await declaredSecrets(root, JSON.parse(readFileSync(checksPath, 'utf8'))), process.env);
550	  if (missingSecrets.length && await askForSecrets(token, repo, missingSecrets)) {
551	    console.log(`baselining: asked the owner to configure ${missingSecrets.join(', ')}`);
552	  }
553	
554	  // 5. Pending agentic notes (from the fresh canon clone) + stamp hold.
555	  const { loadMigrations, agenticMigrations } = await import(pathToFileURL(join(tmp, 'migrations/registry.mjs')).href);
556	  const pending = pendingAgentic(agenticMigrations(await loadMigrations()), priorStamp.updated);
557	  if (pending.length) {
558	    const raw = JSON.parse(readFileSync(checksPath, 'utf8'));
559	    raw.claudinite = { ...raw.claudinite, updated: heldStamp(pending) };
560	    writeFileSync(checksPath, JSON.stringify(raw, null, 2) + '\n');
561	  }
562	
563	  // 6. Meaningful change? A stamp-only bump against an unchanged head is not one —
564	  //    revert it and stay quiet (no nightly stamp-only noise).
565	  const changed = git(['-C', root, 'status', '--porcelain'])
566	    .split('\n').map((l) => l.slice(3)).filter(Boolean);
567	  // `materialize` excluded: a materialized delivery key also touches only
568	  // .claudinite-checks.json, and reverting it would re-drift the repo every night
569	  // and never land the repair.
570	  const onlyStamp = changed.length > 0 && !materialize && changed.every((p) => p === '.claudinite-checks.json');
571	  if (onlyStamp && priorStamp.ref === headSha && !pending.length) {
572	    git(['-C', root, 'checkout', '--', '.claudinite-checks.json']);
573	    console.log('baselining: mount already at canon head, nothing changed — agentless, quiet');
574	    return;
575	  }
576	  const meaningfulChange = changed.length > 0;
577	  // What this stage cannot push. Computed here, before the escalation gate, because a
578	  // withheld file is residual work for the agent exactly like a pending agentic note.
579	  const withheld = withheldWorkflowPaths(changed);
580	  if (withheld.length) {
581	    console.log(`baselining: withholding ${withheld.length} workflow file(s) from the push — `
582	      + `the Action token cannot write .github/workflows/; the agent stage lands them: ${withheld.join(', ')}`);
583	  }
584	
585	  // 6b. SELF-TEST the converged tree before judging its content. This asks "can
586	  //     Claudinite still run here?" — mount, stamp, pack manifests, hook targets,
587	  //     mounted skills, cron, migrations registry — and it is the gate that would
588	  //     have caught #555 the night it landed: a required manifest field arrived
589	  //     with no migration, every consumer pack stopped validating, and because a
590	  //     pack that fails validation contributes NO rules, check_the_world went on
591	  //     reporting green about a corpus it was no longer running. A content check
592	  //     cannot see its own machinery break. This runs on the just-converged tree,
593	  //     so it judges what the member is about to live with.
594	  const selftest = runSelfTest(root);
595	  if (!selftest.ok) {
596	    console.log('baselining: the converged mount FAILED its self-test — requesting the agent');
597	    logGateOutput('selftest --strict', selftest);
598	  }
599	
600	  // 7. Escalation gate: run the conformance checks only when a change happened and
601	  //    no agentic note already forces the agent. A failed self-test forces it too:
602	  //    broken machinery is exactly the judgment case, and merging it would spread
603	  //    the breakage to a repo that was working an hour ago.
604	  const checks = (meaningfulChange && !pending.length) ? runCheckTheWorld(root) : GATE_ABSENT;
605	  if (!checks.ok) logGateOutput('check_the_world', checks);
606	  const reason = escalation({
607	    pendingCount: pending.length, meaningfulChange, checksPass: checks.ok, selftestOk: selftest.ok,
608	    withheldCount: withheld.length, checksCrashed: checks.crashed, selftestCrashed: selftest.crashed,
609	  });
610	  const requestAgent = reason !== null;
611	
612	  // 7b. A REHEARSAL stops here. It has done the only thing it was for — converged
613	  //     this real repo against a canon BRANCH and asked whether the result still
614	  //     works — and now it must leave no trace: no commit, no branch, no PR, and
615	  //     above all no stamp. Stamping a branch head would leave the member
616	  //     `ref-not-on-trunk`, which the #328 anti-rewind guard then refuses to
617	  //     converge over: a rehearsal that wedged the repo it was rehearsing on.
618	  //     `git checkout -- .` restores the working tree wholesale, so the mount goes
619	  //     back to the vendored snapshot the repo actually runs.
620	  if (source.rehearsal) {
621	    git(['-C', root, 'checkout', '--', '.']);
622	    const verdict = selftest.ok && checks.ok ? 'PASS' : 'FAIL';
623	    console.log(`baselining: rehearsal ${verdict} — selftest ${selftest.ok ? 'ok' : 'FAILED'}, `
624	      + `checks ${checks.ok ? 'green' : 'RED'}, ${changed.length} file(s) would have changed. Working tree restored.`);
625	    if (verdict === 'FAIL') process.exit(1);   // the canary's whole purpose: fail the canon PR
626	    return;
627	  }
628	
629	  // 8. Deliver the converge (only when there's something to land).
630	  if (meaningfulChange || pending.length) {
631	    const seed = Math.random().toString(36).slice(2, 8);
632	    delivered = await deliver(root, repo, base, token, delivery, seed, withheld);
633	    console.log(`baselining: delivered converge on ${delivered.branch}${delivered.pr ? ` (PR #${delivered.pr}${delivered.merged ? ', merged' : ''})` : ''} (${delivery})`);
634	  } else {
635	    console.log('baselining: no change to deliver');
636	  }
637	
638	  // 9. Request the agent only when judgment is left (conditional handoff, §3) — naming
639	  //    what this run created AND why the agent is being woken. `delivered` stays null
640	  //    when nothing was opened, and the issue then names nothing; `reason` is non-null
641	  //    exactly when the agent is requested at all.
642	  if (requestAgent && requestFile) {
643	    writeFileSync(requestFile, `${JSON.stringify({ marker: AGENT_REQUEST_MARKER, delivered, reason })}\n`);
644	  }
645	  console.log(requestAgent
646	    ? `baselining: requested agent stage (${reason.code}: ${reason.detail})`
647	    : 'baselining: agentless night — deterministic converge delivered, no agent needed');
648	}
649	
650	// Run only when invoked directly (the scheduler's `node worker.mjs`), never on
651	// import — a test imports the pure helpers without any git or network.
652	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
653	  main().catch((e) => { console.error(`baselining preprocessing failed: ${e.message}`); process.exit(1); });
654	}
655

1	// Post-hoc enforcement of a task's declared outcome ceiling (per-project-scheduling
2	// DESIGN §1, §5.5). The executor runs this in code AFTER the subagent finishes:
3	// the outcome is a ceiling enforced, not merely requested in prose, so a `none`
4	// task that opened a PR — or an `open-pr` task that merged one — fails the run
5	// and converges to needs-human. "No change" is always legal.
6	//
7	// Pushes to non-default branches (e.g. the conversation-logs prune) are outside
8	// the PR taxonomy (DESIGN §1) and are not judged here — the caller passes only
9	// what the task did to PULL REQUESTS.
10	
11	import { OUTCOMES } from './task-contract.mjs';
12	
13	// Verify what a task actually did against its declared ceiling.
14	//   outcome    — the task's declared ceiling ('none' | 'open-pr' | 'merged-pr')
15	//   openedPr   — did the run open a pull request?
16	//   mergedPr   — did the run merge (or arm auto-merge on) a pull request?
17	// Returns { ok, violation } — violation is null when within the ceiling.
18	export function verifyOutcome({ outcome, openedPr = false, mergedPr = false }) {
19	  if (!OUTCOMES.includes(outcome)) {
20	    return { ok: false, violation: `unknown outcome ceiling "${outcome}"` };
21	  }
22	  // Merging implies a PR exists; treat a merge as also having opened one so a
23	  // caller that only reports mergedPr is still judged correctly.
24	  const opened = openedPr || mergedPr;
25	
26	  if (outcome === 'none' && opened) {
27	    return { ok: false, violation: 'a "none" task must not open or merge a pull request' };
28	  }
29	  if (outcome === 'open-pr' && mergedPr) {
30	    return { ok: false, violation: 'an "open-pr" task must not merge a pull request' };
31	  }
32	  return { ok: true, violation: null };
33	}
